  IF v_uid IS NULL THEN RETURN; END IF;
  IF public.hrms_is_admin_user(v_uid)
     OR EXISTS (
       SELECT 1
       FROM public.hrms_active_grants(v_uid) g
       JOIN public.permissions c
         ON g.permission = c.permission_key OR g.permission = ANY (c.aliases)
       WHERE g.scope = 'GLOBAL'
         AND (c.scoped
              OR c.permission_key IN ('teams.manage', 'birthdays.manage', 'notifications.send',
                                      'permissions.view', 'permissions.assign', 'permissions.revoke'))) THEN
    RETURN QUERY SELECT p.id FROM public.profiles p;
    RETURN;
  END IF;
  RETURN QUERY
    SELECT v_uid
    UNION
    SELECT m FROM public.hrms_active_grants(v_uid) g
    CROSS JOIN LATERAL public.hrms_scope_member_ids(g.scope, g.scope_id, v_uid) m
    WHERE g.scope <> 'GLOBAL';
END;
$$;

-- from supabase/migrations/20261006120000_scope_permission_engine.sql
CREATE OR REPLACE FUNCTION public.hrms_audit_user_permissions()
RETURNS trigger
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, pg_temp
AS $$
DECLARE
  v_row     public.user_permissions%ROWTYPE;
  v_action  text;
  v_actor   uuid := auth.uid();
  v_reason  text := nullif(current_setting('hrms.permission_reason', true), '');
BEGIN
  IF TG_OP = 'INSERT' THEN
    v_row := NEW; v_action := 'GRANT'; v_actor := coalesce(v_actor, NEW.created_by);
  ELSIF TG_OP = 'DELETE' THEN
    v_row := OLD; v_action := 'DELETE';
  ELSIF NEW.revoked_at IS NOT NULL AND OLD.revoked_at IS NULL THEN
    v_row := NEW; v_action := 'REVOKE'; v_actor := coalesce(v_actor, NEW.revoked_by);
    v_reason := coalesce(v_reason, NEW.reason);
  ELSE
    v_row := NEW; v_action := 'UPDATE';
  END IF;

  EXECUTE format(
    'INSERT INTO public.permission_audit_logs
       (actor_id, actor_user_id, performed_by, target_user_id, permission, permission_key,
        action, scope, scope_id, reason, metadata, created_at)
     VALUES ($1, $1, $1, $2, $3, $3, $4, %L, $5, $6, $7, now())',
    v_row.scope::text)
  USING v_actor, v_row.user_id, v_row.permission, v_action, v_row.scope_id, v_reason,
        CASE WHEN TG_OP = 'UPDATE'
             THEN jsonb_build_object('old', to_jsonb(OLD), 'new', to_jsonb(NEW))
             ELSE jsonb_build_object('row', to_jsonb(v_row)) END;

  RETURN NULL;
END;
$$;

-- from supabase/migrations/20260917070000_cache_manager_team_hierarchy.sql
CREATE OR REPLACE FUNCTION public.current_user_can_review(employee_id uuid DEFAULT NULL)
RETURNS boolean
LANGUAGE sql
STABLE
SECURITY DEFINER
SET search_path = public, pg_temp
AS $$
  SELECT
    -- 1. Caller is a system/hr admin → can review anyone
    EXISTS (
      SELECT 1 FROM public.profiles me
      WHERE me.id = auth.uid()
        AND me.is_active = true
        AND me.role IN ('SYSTEM_ADMIN', 'ADMIN', 'HR', 'HRD')
    )
    OR
    -- 2. Called without a specific employee → "can I review anyone?" check
    (employee_id IS NULL AND EXISTS (
      SELECT 1 FROM public.manager_team_cache
      WHERE manager_id = auth.uid()
      LIMIT 1
    ))
    OR
    -- 3. Called for a specific employee → O(1) index lookup
    (employee_id IS NOT NULL AND EXISTS (
      SELECT 1 FROM public.manager_team_cache
      WHERE manager_id    = auth.uid()
        AND subordinate_id = employee_id
    ));
$$;

-- from supabase/migrations/20260901000000_comprehensive_production_rls_remediation.sql
CREATE OR REPLACE FUNCTION public.can_view_tracking_user(p_user_id uuid)
RETURNS boolean
LANGUAGE sql
STABLE
SECURITY DEFINER
SET search_path = public, pg_temp
AS $$
  SELECT
    p_user_id = auth.uid()
    OR EXISTS (
      SELECT 1
      FROM public.profiles employee
      WHERE employee.id = p_user_id
        AND employee.reports_to = auth.uid()
        AND employee.is_active = true
    )
    OR EXISTS (
      SELECT 1
      FROM public.profiles actor
      WHERE actor.id = auth.uid()
        AND actor.is_active = true
        AND public.normalize_profile_role(actor.role) IN ('SYSTEM_ADMIN', 'ADMIN', 'HR', 'HRD')
    );
$$;

-- from supabase/migrations/20261008200000_location_monitoring_phase3.sql
CREATE OR REPLACE FUNCTION public.hrms_can_view_location(p_target uuid)
RETURNS boolean
LANGUAGE plpgsql
STABLE
SECURITY DEFINER
SET search_path = public, pg_temp
AS $$
DECLARE
  v_uid uuid := auth.uid();
BEGIN
  IF v_uid IS NULL OR p_target IS NULL THEN RETURN false; END IF;
  IF p_target = v_uid OR public.hrms_is_admin_user(v_uid) THEN RETURN true; END IF;
  IF EXISTS (
    SELECT 1 FROM public.user_permissions up
    WHERE up.user_id = v_uid AND up.revoked_at IS NULL AND (up.expires_at IS NULL OR up.expires_at > now())
      AND up.scope::text = 'GLOBAL' AND up.permission IN ('live_tracking.view', 'attendance.view')) THEN
    RETURN true;
  END IF;
  IF public.can_view_tracking_user(p_target) THEN RETURN true; END IF;
  -- Anyone below the caller in the reporting tree.
  IF EXISTS (
    WITH RECURSIVE chain AS (
      SELECT p.id, p.reports_to, 1 AS depth FROM public.profiles p WHERE p.id = p_target
      UNION ALL
      SELECT m.id, m.reports_to, c.depth + 1
      FROM chain c JOIN public.profiles m ON m.id = c.reports_to
      WHERE c.depth < 12
    )
    SELECT 1 FROM chain WHERE reports_to = v_uid
  ) THEN
    RETURN true;
  END IF;
  RETURN p_target IN (SELECT public.authorized_user_ids('live_tracking.view'))
      OR p_target IN (SELECT public.authorized_user_ids('attendance.view'));
END;
$$;

-- from supabase/migrations/20261006190000_qa_phone_uniqueness_and_leave_reset.sql
CREATE OR REPLACE FUNCTION public.rpc_admin_reset_all_leave_balances(
  p_leave_type text,
  p_female_days numeric,
  p_male_days numeric,
  p_reason text
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, pg_temp
AS $$
DECLARE
  v_type    text := upper(btrim(coalesce(p_leave_type, '')));
  v_emp     record;
  v_current numeric;
  v_target  numeric;
  v_delta   numeric;
  v_count   int := 0;
  v_run     text := gen_random_uuid()::text;
BEGIN
  IF auth.uid() IS NULL OR NOT EXISTS (
    SELECT 1 FROM public.profiles
    WHERE id = auth.uid()
      AND coalesce(is_active, true)
      AND upper(role) IN ('SYSTEM_ADMIN', 'SUPER_ADMIN', 'ADMIN', 'HR', 'HRD')
  ) THEN
    RAISE EXCEPTION 'ADMIN_PERMISSION_REQUIRED';
  END IF;
  IF v_type NOT IN ('SICK', 'CASUAL', 'EARNED', 'COMP_OFF') THEN
    RAISE EXCEPTION 'INVALID_LEAVE_TYPE';
  END IF;
  IF p_female_days IS NULL OR p_male_days IS NULL
     OR p_female_days < 0 OR p_male_days < 0
     OR p_female_days > 365 OR p_male_days > 365 THEN
    RAISE EXCEPTION 'INVALID_ADJUSTMENT_QUANTITY';
  END IF;
  IF length(btrim(coalesce(p_reason, ''))) < 3 THEN
    RAISE EXCEPTION 'ADJUSTMENT_REASON_REQUIRED';
  END IF;

  FOR v_emp IN
    SELECT p.id, upper(coalesce(p.gender, '')) AS gender
    FROM public.profiles p
    WHERE p.is_active
      AND NOT coalesce(p.is_service_account, false)
  LOOP
    IF v_emp.gender = 'FEMALE' THEN
      v_target := p_female_days;
    ELSIF v_emp.gender = 'MALE' THEN
      v_target := p_male_days;
    ELSE
      CONTINUE;
    END IF;

    EXECUTE format('SELECT coalesce(%I, 0) FROM public.leave_balance WHERE user_id = $1', lower(v_type))
      INTO v_current USING v_emp.id;
    v_delta := v_target - coalesce(v_current, 0);

    IF v_delta <> 0 THEN
      PERFORM public.apply_leave_transaction(
        v_emp.id, v_type,
        CASE WHEN v_delta > 0 THEN 'MANUAL_CREDIT' ELSE 'MANUAL_DEBIT' END,
        v_delta,
        (now() AT TIME ZONE 'Asia/Kolkata')::date,
        null, 'HR_MANUAL', null, btrim(p_reason), auth.uid(),
        'reset-all:' || v_run || ':' || v_emp.id);
      v_count := v_count + 1;
    END IF;
  END LOOP;

  BEGIN  -- audit is best effort; every balance change is already in leave_transactions
    INSERT INTO public.hrms_audit_events(actor_user_id, target_user_id, action, entity_type, entity_id, new_values, source)
    VALUES (auth.uid(), null, 'LEAVE_BALANCE_RESET_ALL', 'leave_balance', auth.uid(),
            jsonb_build_object('leave_type', v_type, 'female_days', p_female_days,
                               'male_days', p_male_days, 'reason', btrim(p_reason),
                               'employees_updated', v_count),
            'HRMS_ADMIN');
  EXCEPTION WHEN others THEN
    NULL;
  END;

  RETURN jsonb_build_object('success', true, 'employees_updated', v_count);
END;
$$;

-- from supabase/migrations/20260907020000_fix_biometric_assignment_and_smartoffice_proxy.sql
CREATE OR REPLACE FUNCTION public.rpc_assign_biometric_employee_code(
  p_profile_id uuid,
  p_employee_code text
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, pg_temp
AS $$
DECLARE
  v_actor uuid := auth.uid();
  v_role text;
  v_code text := nullif(btrim(p_employee_code), '');
  v_previous_code text;
  v_conflicting_profile uuid;
  v_conflicting_name text;
BEGIN
  -- 1. Authorize Admin or Service Role
  IF coalesce(auth.role(), '') <> 'service_role' THEN
    SELECT upper(coalesce(profile.role, ''))
    INTO v_role
    FROM public.profiles profile
    WHERE profile.id = v_actor AND profile.is_active = true;

    IF coalesce(v_role, '') NOT IN ('SYSTEM_ADMIN', 'SUPER_ADMIN', 'ADMIN', 'HR', 'HRD') THEN
      RAISE EXCEPTION 'ADMIN_PERMISSION_REQUIRED';
    END IF;
  END IF;

  -- 2. Validate Code
  IF v_code IS NULL THEN
    RAISE EXCEPTION 'BIOMETRIC_EMPLOYEE_CODE_REQUIRED';
  END IF;

  -- 3. Verify Target Profile Exists
  SELECT smartoffice_employee_code INTO v_previous_code
  FROM public.profiles
  WHERE id = p_profile_id AND is_active = true
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'ACTIVE_HRMS_PROFILE_NOT_FOUND';
  END IF;

  -- 4. Check if Code is currently held by another profile
  SELECT id, name INTO v_conflicting_profile, v_conflicting_name
  FROM public.profiles
  WHERE lower(btrim(smartoffice_employee_code)) = lower(v_code)
    AND id <> p_profile_id
  LIMIT 1;

  -- If held by another profile, reassign safely:
  IF v_conflicting_profile IS NOT NULL THEN
    -- Clear from previous holder
    UPDATE public.profiles
    SET smartoffice_employee_code = NULL,
        smartoffice_synced_at = now(),
        updated_at = now()
    WHERE id = v_conflicting_profile;

    -- Record audit log for unassignment of previous holder
    INSERT INTO public.biometric_mapping_audit(
      profile_id, actor_id, action, previous_employee_code, new_employee_code
    ) VALUES (
      v_conflicting_profile,
      v_actor,
      'UNASSIGNED',
      v_code,
      NULL
    );
  END IF;

  -- 5. Clear old device logs if employee had a previous different code
  IF v_previous_code IS NOT NULL AND lower(btrim(v_previous_code)) <> lower(v_code) THEN
    UPDATE public.smartoffice_device_logs
    SET user_id = NULL
    WHERE user_id = p_profile_id
      AND lower(btrim(employee_code)) = lower(btrim(v_previous_code));
  END IF;

  -- 6. Assign code to target profile
  UPDATE public.profiles
  SET smartoffice_employee_code = v_code,
      smartoffice_synced_at = now(),
      updated_at = now()
  WHERE id = p_profile_id;

  -- 7. Link all device logs for this code to the target profile
  UPDATE public.smartoffice_device_logs
  SET user_id = p_profile_id
  WHERE lower(btrim(employee_code)) = lower(v_code);

  -- 8. Record audit log for target profile
  INSERT INTO public.biometric_mapping_audit(
    profile_id, actor_id, action, previous_employee_code, new_employee_code
  ) VALUES (
    p_profile_id,
    v_actor,
    CASE
      WHEN v_previous_code IS NULL THEN 'ASSIGNED'
      WHEN lower(btrim(v_previous_code)) = lower(v_code) THEN 'ASSIGNED'
      ELSE 'REPLACED'
    END,
    v_previous_code,
    v_code
  );

  RETURN jsonb_build_object(
    'success', true,
    'profile_id', p_profile_id,
    'employee_code', v_code,
    'reassigned_from', v_conflicting_profile,
    'reassigned_name', v_conflicting_name
  );
END;
$$;

-- from supabase/migrations/20260727020000_biometric_authoritative_attendance.sql
create or replace function public.rpc_unassign_biometric_employee_code(
  p_profile_id uuid
)
returns jsonb
language plpgsql
security definer
set search_path = public
as $$
declare
  v_actor uuid := auth.uid();
  v_role text;
  v_previous_code text;
begin
  if coalesce(auth.role(), '') <> 'service_role' then
    select upper(coalesce(role, '')) into v_role
    from public.profiles
    where id = v_actor and is_active = true;

    if coalesce(v_role, '') not in
      ('SYSTEM_ADMIN', 'SUPER_ADMIN', 'ADMIN', 'HR', 'HRD') then
      raise exception 'ADMIN_PERMISSION_REQUIRED';
    end if;
  end if;

  select smartoffice_employee_code into v_previous_code
  from public.profiles
  where id = p_profile_id
  for update;
  if not found then
    raise exception 'HRMS_PROFILE_NOT_FOUND';
  end if;

  update public.profiles
  set smartoffice_employee_code = null,
      smartoffice_synced_at = now()
  where id = p_profile_id;

  if v_previous_code is not null then
    update public.smartoffice_device_logs
    set user_id = null
    where user_id = p_profile_id
      and lower(btrim(employee_code)) = lower(btrim(v_previous_code));
  end if;

  insert into public.biometric_mapping_audit(
    profile_id, actor_id, action, previous_employee_code, new_employee_code
  ) values (
    p_profile_id, v_actor, 'UNASSIGNED', v_previous_code, null
  );

  return jsonb_build_object(
    'success', true,
    'profile_id', p_profile_id
  );
end;
$$;

-- from supabase/migrations/20260803040000_attendance_field_biometric_location_optimization.sql
create or replace function public.reprocess_unmatched_biometric_punches(p_limit integer default 500)
returns jsonb language plpgsql security definer set search_path=public,pg_temp
as $$
declare v_row record;v_processed int:=0;v_result jsonb;
begin
  if auth.role()<>'service_role' and not public.is_profile_admin() then
    raise exception 'BIOMETRIC_RECONCILIATION_PERMISSION_REQUIRED';
  end if;
  for v_row in select id,punch_timestamp from public.biometric_device_punches
    where processing_status in('UNMAPPED','RECEIVED') order by punch_timestamp limit least(greatest(p_limit,1),1000)
  loop
    v_result:=public.process_biometric_punch(v_row.id,v_row.punch_timestamp);
    if v_result->>'status' is distinct from 'UNMAPPED' then v_processed:=v_processed+1; end if;
  end loop;
  update public.biometric_reconciliation_queue q set status='RESOLVED',resolved_by=auth.uid(),resolved_at=now()
  where status='OPEN' and exists(
    select 1 from public.biometric_device_punches p
    where p.id=q.punch_id and p.punch_timestamp=q.punch_timestamp and p.processing_status='PROCESSED');
  return jsonb_build_object('success',true,'processed',v_processed);
end $$;

-- from supabase/migrations/20260730230000_sync_idempotency_monitoring_and_release.sql
create or replace function public.rpc_admin_sync_smartoffice_profiles_batch(
  p_batch_id uuid,
  p_payload_hash text,
  p_rows jsonb
)
returns jsonb
language plpgsql
security definer
set search_path = public, pg_temp
as $$
declare
  v_actor uuid := auth.uid();
  v_existing public.smartoffice_profile_sync_batches%rowtype;
  v_submitted integer;
  v_updated integer;
  v_result jsonb;
begin
  if v_actor is null or not public.is_hrms_admin(v_actor) then
    raise exception 'ADMIN_PERMISSION_REQUIRED';
  end if;
  if p_batch_id is null
     or p_payload_hash !~ '^[0-9a-f]{64}$'
     or jsonb_typeof(p_rows) <> 'array' then
    raise exception 'INVALID_SMARTOFFICE_SYNC_BATCH';
  end if;

  select * into v_existing
  from public.smartoffice_profile_sync_batches
  where batch_id = p_batch_id;
  if found then
    if v_existing.requested_by <> v_actor
       or v_existing.payload_hash <> p_payload_hash then
      raise exception 'SMARTOFFICE_SYNC_BATCH_CONFLICT';
    end if;
    return v_existing.result || jsonb_build_object('idempotent_replay', true);
  end if;

  v_submitted := jsonb_array_length(p_rows);
  if v_submitted < 1 or v_submitted > 5000 then
    raise exception 'SMARTOFFICE_SYNC_ROW_LIMIT';
  end if;

  if exists (
    select 1
    from jsonb_array_elements(p_rows) row_value
    where nullif(btrim(row_value->>'employee_code'), '') is null
  ) or exists (
    select 1
    from jsonb_array_elements(p_rows) row_value
    group by lower(btrim(row_value->>'employee_code'))
    having count(*) > 1
  ) then
    raise exception 'SMARTOFFICE_SYNC_DUPLICATE_OR_BLANK_CODE';
  end if;

  if exists (
    select 1
    from jsonb_array_elements(p_rows) row_value
    where (
      select count(*)
      from public.profiles p
      where p.is_active
        and lower(btrim(coalesce(p.smartoffice_employee_code, ''))) =
          lower(btrim(row_value->>'employee_code'))
    ) <> 1
  ) then
    raise exception 'SMARTOFFICE_SYNC_PROFILE_MAPPING_NOT_UNIQUE';
  end if;

  with input_rows as (
    select
      btrim(value->>'employee_code') as employee_code,
      nullif(btrim(value->>'name'), '') as name,
      nullif(lower(btrim(value->>'email')), '') as email,
      nullif(regexp_replace(value->>'phone', '\D', '', 'g'), '') as phone,
      nullif(btrim(value->>'smartoffice_department'), '') as department,
      nullif(btrim(value->>'smartoffice_designation'), '') as designation,
      nullif(btrim(value->>'smartoffice_grade'), '') as grade,
      nullif(btrim(value->>'smartoffice_location'), '') as location,
      nullif(btrim(value->>'smartoffice_company'), '') as company,
      nullif(btrim(value->>'smartoffice_team'), '') as team
    from jsonb_array_elements(p_rows)
  ),
  updated as (
    update public.profiles p
    set
      name = coalesce(i.name, p.name),
      email = coalesce(i.email, p.email),
      phone = coalesce(i.phone, p.phone),
      smartoffice_department = i.department,
      smartoffice_designation = i.designation,
      smartoffice_grade = i.grade,
      smartoffice_location = i.location,
      smartoffice_company = i.company,
      smartoffice_team = i.team,
      smartoffice_synced_at = now(),
      updated_at = now()
    from input_rows i
    where p.is_active
      and lower(btrim(p.smartoffice_employee_code)) =
        lower(btrim(i.employee_code))
    returning p.id
  )
  select count(*) into v_updated from updated;

  if v_updated <> v_submitted then
    raise exception 'SMARTOFFICE_SYNC_COUNT_MISMATCH';
  end if;

  v_result := jsonb_build_object(
    'success', true,
    'transaction_status', 'COMMITTED',
    'batch_id', p_batch_id,
    'payload_hash', p_payload_hash,
    'submitted_count', v_submitted,
    'updated_count', v_updated,
    'rejected_count', 0,
    'idempotent_replay', false
  );
  insert into public.smartoffice_profile_sync_batches(
    batch_id, requested_by, payload_hash, submitted_count,
    updated_count, status, result
  ) values (
    p_batch_id, v_actor, p_payload_hash, v_submitted,
    v_updated, 'COMMITTED', v_result
  );
  return v_result;
end;
$$;

RESET check_function_bodies;
CREATE TRIGGER hrms_audit_user_permissions AFTER INSERT OR UPDATE OR DELETE ON public.user_permissions
  FOR EACH ROW EXECUTE FUNCTION public.hrms_audit_user_permissions();
-- access rules as deployed (20260901000000 / 20261006120000 / 20261007120000)
CREATE POLICY attendance_logs_employee_select ON public.attendance_logs FOR SELECT TO authenticated
  USING (user_id = auth.uid() OR public.current_user_can_review(user_id));
CREATE POLICY leave_self_or_review_update ON public.leave_requests FOR UPDATE TO authenticated
  USING (user_id = auth.uid() OR public.current_user_can_review(user_id))
  WITH CHECK (user_id = auth.uid() OR public.current_user_can_review(user_id));
CREATE POLICY leave_self_select ON public.leave_requests FOR SELECT TO authenticated USING (true);
CREATE POLICY location_tracking_select ON public.location_tracking FOR SELECT TO authenticated
  USING (public.can_view_tracking_user(user_id));
ALTER TABLE public.location_tracking ENABLE ROW LEVEL SECURITY;
CREATE POLICY hrms_user_permissions_read ON public.user_permissions FOR SELECT TO authenticated USING (true);
CREATE POLICY hrms_user_permissions_admin_write ON public.user_permissions FOR ALL TO authenticated
  USING (public.hrms_is_permission_admin(auth.uid(), 'assign'))
  WITH CHECK (public.hrms_is_permission_admin(auth.uid(), 'assign') AND user_id <> auth.uid());
CREATE POLICY tasks_select_all ON public.tasks FOR SELECT TO authenticated USING (true);
CREATE POLICY tasks_authorized_insert ON public.tasks FOR INSERT TO authenticated
  WITH CHECK (assigned_by = auth.uid() OR public.is_profile_admin());
CREATE POLICY hrms_scoped_insert_tasks ON public.tasks FOR INSERT TO authenticated
  WITH CHECK (assigned_to IN (SELECT public.authorized_user_ids('tasks.manage')));
-- a stand-in core for the leave-balance wrapper
CREATE FUNCTION public.rpc_admin_adjust_leave_balance(p_user_id uuid, p_days numeric) RETURNS jsonb
LANGUAGE sql SECURITY DEFINER AS $$ SELECT jsonb_build_object('success', true, 'user_id', p_user_id) $$;
SELECT public.hrms_install_permission_wrapper('rpc_admin_adjust_leave_balance',
  $k$ARRAY['leave.balance.manage']$k$, $t$ARRAY[p_user_id]$t$);
